      "content": "{\n  \"name\": \"deepseek-harness-vscode\",\n  \"displayName\": \"DeepSeek Harness for VSCode\",\n  \"description\": \"DeepSeek Harness (DSH) 的 VS Code 接入：侧边栏/标签页忠实呈现 DSH Web GUI 并自动检测启动，不影响用户对 DSH 本身的页面组织、第三方插件装配等二次开发行为；v0.7.13 起把 DSH 注册为 Copilot 聊天模型——模型选择器里出现 DeepSeek Harness 下属模型条目，接收 Copilot 组织好的现成对话、滤除对话内容无关的 prompt、交给 DSH 二次组织、流式回写，旨在利用 DSH 强大的任务编排与工具调用能力，发挥最大性能；v1.0.1 起自动识别官网 Windows 桌面版，用其内置 dsh CLI 启动（无需 npm/Node）；v1.1.0 起在 Remote-WSL / Remote-SSH 面板里用本机浏览器完成 DeepSeek 账号登录；v1.1.1 起面板内复制按钮经宿主剪贴板中继恢复可用\",\n  \"version\": \"1.1.1\",\n  \"publisher\": \"vithrive\",\n  \"license\": \"MIT\",\n  \"icon\": \"media/icon.png\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Vithrive/Deepseek-Harness-for-VS-Code.git\"\n  },\n  \"engines\": {\n    \"vscode\": \"^1.75.0\"\n  },\n  \"categories\": [\n    \"Other\"\n  ],\n  \"main\": \"./extension.js\",\n  \"extensionKind\": [\n    \"workspace\"\n  ],\n  \"activationEvents\": [\n    \"onView:dsh.webview\",\n    \"onCommand:dshPanel.resetChatMapping\",\n    \"onCommand:dshPanel.chatStatus\",\n    \"onStartupFinished\"\n  ],\n  \"contributes\": {\n    \"languageModelChatProviders\": [\n      {\n        \"vendor\": \"dsh\",\n        \"displayName\": \"DeepSeek Harness\"\n      }\n    ],\n    \"configuration\": {\n      \"title\": \"DeepSeek Harness Panel\",\n      \"properties\": {\n        \"dshPanel.url\": {\n          \"type\": \"string\",\n          \"default\": \"http://127.0.0.1:3080\",\n          \"description\": \"DeepSeek Harness Web GUI 地址（本地或通过 SSH 隧道转发的地址）\"\n        },\n        \"dshPanel.host\": {\n          \"type\": \"string\",\n          \"default\": \"127.0.0.1\",\n          \"description\": \"自动启动 dsh 时绑定的主机地址\"\n        },\n        \"dshPanel.port\": {\n          \"type\": \"number\",\n          \"default\": 3080,\n          \"description\": \"自动启动 dsh 时监听的端口\"\n        },\n        \"dshPanel.autoStart\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"检测到 DSH 未运行时，是否自动执行 dsh web 启动它\"\n        },\n        \"dshPanel.autoRegisterWorkspace\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"是否把 VS Code 当前工作区自动注册为 DSH 工作区（新会话默认使用该工作区）\"\n        },\n        \"dshPanel.openSystemBrowser\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"description\": \"扩展启动 dsh web 时是否保留弹系统浏览器的旧行为（默认关闭：新版 dsh web 的浏览器认证由扩展自动完成，面板内即用）\"\n        },\n        \"dshPanel.installClipboardPlugin\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"自动安装内置 dsh-webview-clipboard 插件（v0.3.0 起：跨平台把面板内 navigator.clipboard.writeText 经宿主中继写入剪贴板，修复复制按钮静默失效；并修复 macOS 面板内复制/粘贴等编辑快捷键失效）。若怀疑影响 dsh web 启动可关闭后对比\"\n        },\n        \"dshPanel.installOpenExternalPlugin\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"自动安装内置 dsh-vscode-open-external 插件（v1.1.0 起）：面板内 DSH 页面里的 window.open（典型：DeepSeek 账号登录的授权页）改为在本机系统浏览器打开——Remote-SSH / Remote-WSL 场景下由客户端（如 Windows）浏览器打开，解决远端没有图形浏览器时无法登录的问题\"\n        },\n        \"dshPanel.workspaceFileLinkAction\": {\n          \"type\": \"string\",\n          \"default\": \"revealAndOpen\",\n          \"enum\": [\n            \"revealAndOpen\",\n            \"revealOnly\",\n            \"off\"\n          ],\n          \"enumDescriptions\": [\n            \"点击 DSH 对话里的工作区文件/文件夹链接时，在 VS Code 资源管理器中定位并打开（文件打开编辑器，文件夹仅定位）\",\n            \"只在本窗口的 VS Code 资源管理器中定位并选中，不额外打开编辑器\",\n            \"不接管：保持 DSH 自身行为（在 DSH 侧边栏打开）。此时也不会安装配套插件 dsh-vscode-file-links\"\n          ],\n          \"description\": \"DSH 对话里的工作区文件/文件夹链接点击行为（自动安装配套插件 dsh-vscode-file-links 实现）。只有目标位于当前 VS Code 工作区内且真实存在时才接管，否则保持 DSH 侧边栏打开；按住 Ctrl/Cmd/Shift/Alt 点击可临时走 DSH 侧边栏\"\n        },\n        \"dshPanel.autoInstallDsh\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"检测到当前环境（含远程服务器）未安装 dsh 时，是否提示并代为安装（npm install -g @deepseek-ai/dsh）。注：官网 Windows 桌面版会被自动识别，不会走到这里\"\n        },\n        \"dshPanel.dshCommand\": {\n          \"type\": \"string\",\n          \"default\": \"dsh\",\n          \"description\": \"dsh 命令（默认从 PATH 解析；未找到时自动尝试官网 Windows 桌面版内置 CLI 与 npx。如需强制指定完整路径，例如 C:\\\\Users\\\\you\\\\AppData\\\\Roaming\\\\npm\\\\dsh.cmd 或 <桌面版安装目录>\\\\resources\\\\runtime\\\\cli\\\\bin\\\\dsh.cmd）\"\n        },\n        \"dshPanel.remoteAuthProxy\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"Remote-SSH / Dev Containers 等真远程窗口下是否启用受管认证代理（默认启用）：扩展在服务器回环起代理并经端口转发交给 webview，使面板与 Copilot 桥接免登录。代理只监听服务器回环，但同机的其他用户若枚举到该端口，可借它访问你的 DSH（绕过启动令牌）。多用户共享服务器建议关闭，此时面板会给出浏览器认证引导\"\n        },\n        \"dshPanel.killOnDispose\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"扩展停用或 VS Code 关闭时，是否结束由本扩展启动的 dsh 进程（不影响你手动启动的 dsh）\"\n        },\n        \"dshPanel.chatAgentPreset\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"description\": \"DSH 模型会话创建时使用的 agent 预设（如 liangshen）；留空=DSH 设置里的默认预设\"\n        },\n        \"dshPanel.chatProvider\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"description\": \"DSH (DeepSeek Harness) 模型条目使用的模型提供方（provider id，需已在 DSH 设置中配置，如 deepseek-official）；留空=跟随 DSH 默认模型\"\n        },\n        \"dshPanel.chatModel\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"description\": \"DSH (DeepSeek Harness) 模型条目使用的模型 id（与 chatProvider 配合，如 deepseek-flash、deepseek-v4-pro）；留空=跟随 DSH 默认模型\"\n        },\n        \"dshPanel.chatTimeoutMs\": {\n          \"type\": \"number\",\n          \"default\": 900000,\n          \"description\": \"单次任务最长等待时间（毫秒），超时后任务仍在 DSH 面板运行\"\n        },\n        \"dshPanel.chatSyncLookbackMin\": {\n          \"type\": \"number\",\n          \"default\": 60,\n          \"description\": \"定位当前 Copilot 聊天时，扫描最近多少分钟内修改过的聊天会话文件\"\n        },\n        \"dshPanel.enableDshModel\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"把 DSH 注册为 VS Code 聊天模型（模型选择器出现 DSH (DeepSeek Harness)），选中即由 DSH 解题\"\n        },\n        \"dshPanel.debugModelMessages\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"description\": \"调试：把 VS Code 发给 DSH 模型的消息结构写入工作区 .dsh-debug/ 目录\"\n        },\n        \"dshPanel.markForeignAssistant\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"description\": \"切回 DSH 模型补发中间对话时，是否给其他模型产出的回答加「【Copilot 其他模型回答】」产地标签（帮助 DSH 区分哪些回答不是它自己生成的）；关闭则不标注\"\n        },\n        \"dshPanel.dshReasoningEffort\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"enum\": [\"\", \"off\", \"low\", \"high\", \"max\"],\n          \"description\": \"DSH 模型的推理档位兜底配置（reasoningEffort）：off/low/high/max；聊天界面选择优先，此配置仅在界面未选择时生效；留空=跟随 DSH 默认档位\"\n        }\n      }\n    },\n    \"viewsContainers\": {\n      \"activitybar\": [\n        {\n          \"id\": \"dsh-panel\",\n          \"title\": \"DeepSeek Harness\",\n          \"icon\": \"media/icon.svg\"\n        }\n      ]\n    },\n    \"views\": {\n      \"dsh-panel\": [\n        {\n          \"type\": \"webview\",\n          \"id\": \"dsh.webview\",\n          \"name\": \"DeepSeek Harness\"\n        }\n      ]\n    },\n    \"commands\": [\n      {\n        \"command\": \"dshPanel.openInTab\",\n        \"title\": \"DeepSeek Harness: 在标签页中打开\",\n        \"icon\": \"$(open-preview)\"\n      },\n      {\n        \"command\": \"dshPanel.openInBrowser\",\n        \"title\": \"DeepSeek Harness: 在浏览器中打开\",\n        \"icon\": \"$(globe)\"\n      },\n      {\n        \"command\": \"dshPanel.refresh\",\n        \"title\": \"DeepSeek Harness: 刷新\",\n        \"icon\": \"$(refresh)\"\n      },\n      {\n        \"command\": \"dshPanel.restart\",\n        \"title\": \"DeepSeek Harness: 重启 dsh web\",\n        \"icon\": \"$(debug-restart)\"\n      },\n      {\n        \"command\": \"dsh.sendSelection\",\n        \"title\": \"DeepSeek Harness: 发送选中内容到对话框\"\n      },\n      {\n        \"command\": \"dshPanel.resetChatMapping\",\n        \"title\": \"DeepSeek Harness: 重置 DSH 会话映射\"\n      },\n      {\n        \"command\": \"dshPanel.chatStatus\",\n        \"title\": \"DeepSeek Harness: 检查 DSH 状态\"\n      },\n      {\n        \"command\": \"dshPanel.diagnoseModels\",\n        \"title\": \"DeepSeek Harness: 诊断 DSH 模型注册表\"\n      }\n    ],\n    \"menus\": {\n      \"editor/context\": [\n        {\n          \"command\": \"dsh.sendSelection\",\n          \"when\": \"editorHasSelection\",\n          \"group\": \"9_cutcopypaste@100\"\n        }\n      ],\n      \"view/title\": [\n        {\n          \"command\": \"dshPanel.refresh\",\n          \"when\": \"view == dsh.webview\",\n          \"group\": \"navigation\"\n        },\n        {\n          \"command\": \"dshPanel.restart\",\n          \"when\": \"view == dsh.webview\",\n          \"group\": \"navigation\"\n        },\n        {\n          \"command\": \"dshPanel.openInTab\",\n          \"when\": \"view == dsh.webview\",\n          \"group\": \"navigation\"\n        },\n        {\n          \"command\": \"dshPanel.openInBrowser\",\n          \"when\": \"view == dsh.webview\",\n          \"group\": \"navigation\"\n        }\n      ]\n    }\n  }\n}\n"
    },
